from itertools import combinations
import numpy as np
import matplotlib.pyplot as plt

def simplex_key(simplex):
    return (len(simplex), tuple(simplex))

def close_under_faces(maximal_simplices):
    """Return all non-empty faces, grouped by dimension."""
    simplices = set()
    for maximal in maximal_simplices:
        maximal = tuple(sorted(maximal))
        for size in range(1, len(maximal) + 1):
            simplices.update(combinations(maximal, size))
    max_dim = max(len(s) - 1 for s in simplices)
    return {p: sorted((s for s in simplices if len(s) == p + 1))
            for p in range(max_dim + 1)}

def boundary_matrix(K, p):
    """Matrix of ∂_p over F_2; columns and rows use the displayed bases."""
    columns = K.get(p, [])
    rows = K.get(p - 1, []) if p &gt; 0 else []
    matrix = np.zeros((len(rows), len(columns)), dtype=np.uint8)
    row_index = {simplex: i for i, simplex in enumerate(rows)}
    if p &gt; 0:
        for j, simplex in enumerate(columns):
            for face in combinations(simplex, p):
                matrix[row_index[face], j] = 1
    return matrix

def rank_mod2(matrix):
    """Gaussian elimination over F_2."""
    A = np.array(matrix, dtype=np.uint8, copy=True) % 2
    rank = row = 0
    for col in range(A.shape[1]):
        candidates = np.flatnonzero(A[row:, col])
        if len(candidates) == 0:
            continue
        pivot = row + candidates[0]
        A[[row, pivot]] = A[[pivot, row]]
        for other in range(A.shape[0]):
            if other != row and A[other, col]:
                A[other] ^= A[row]
        rank += 1
        row += 1
        if row == A.shape[0]:
            break
    return rank

def homology_table(K):
    """Dimensions of C_p, Z_p, B_p and H_p over F_2."""
    result = []
    max_dim = max(K)
    for p in range(max_dim + 1):
        dim_C = len(K.get(p, []))
        rank_dp = rank_mod2(boundary_matrix(K, p)) if p &gt; 0 else 0
        rank_next = rank_mod2(boundary_matrix(K, p + 1)) if p &lt; max_dim else 0
        dim_Z = dim_C - rank_dp
        dim_B = rank_next
        result.append((p, dim_C, dim_Z, dim_B, dim_Z - dim_B))
    return result

def report(name, K):
    print(name)
    for p in sorted(K):
        print(f"  basis C_{p}: {K[p]}")
    print("  p | dim C_p | dim Z_p | dim B_p | beta_p")
    for row in homology_table(K):
        print(" ", " | ".join(map(str, row)))

def check_boundary_squared(K):
    for p in range(2, max(K) + 1):
        product = (boundary_matrix(K, p - 1) @ boundary_matrix(K, p)) % 2
        assert not product.any(), f"Boundary squared failed in dimension {p}"
    return True

outline_triangle = close_under_faces([(0, 1), (1, 2), (0, 2)])
filled_triangle = close_under_faces([(0, 1, 2)])
square_loop = close_under_faces([(0, 1), (1, 2), (2, 3), (0, 3)])
hollow_tetrahedron = close_under_faces([(0, 1, 2), (0, 1, 3),
                                        (0, 2, 3), (1, 2, 3)])

complexes = {
    "outline triangle": outline_triangle,
    "filled triangle": filled_triangle,
    "square loop": square_loop,
    "hollow tetrahedron": hollow_tetrahedron,
}
print("Defined four finite simplicial complexes over F_2.")

Story
The interlude should pause the mathematical build and make the complete modelling pipeline explicit: \[\text{scientific system}
\to \text{observed data}
\to \text{data object}
\to K
\to f
\to K_\bullet
\to \underbrace{H_p(K_\bullet)}_{\text{persistence module}}
\to \text{barcode or diagram}
\to \text{summary, comparison or claim}.\] By this point, participants have already encountered most of these choices, but many will have appeared as though they were simply part of the definition. The purpose of the interlude is to expose them as modelling decisions. Persistent homology is not one method applied after the data have been prepared. It is a family of pipelines in which each decision determines what can later be called a component, loop, cavity, birth, death or persistent feature.
▶ Likely sticking point. The persistence module is the evolving homology calculation. The barcode or persistence diagram is the interval-decomposition summary of that module in the ordinary one-parameter setting. The diagram does not erase the modelling history that produced the module.

Examples to revisit
Return to examples already used in Weeks 1–4 and deliberately alter one choice at a time:

noisy circle versus noisy disk: change sampling density, metric or maximum scale;
outline triangle versus filled triangle: keep the same vertices and edges but change whether the two-simplex is included;
merging components: compare ordinary and reduced \(H_0\) and identify the surviving essential class;
a greyscale field: compare sublevel and superlevel filtrations;
an interaction graph: compare graph-cycle homology with clique-complex homology.

The repeated examples should make clear that a different answer need not be a failure of robustness. It may be the mathematically correct consequence of asking a different question.

Learning goals
By the end of this week, you should be able to:

explain repeated or framewise persistence as ordinary persistence applied separately along physical time;
keep physical time, filtration scale and any delay-coordinate parameters distinct when reading a dynamic TDA analysis;
read a CROCKER-style summary and connect a slice of it back to the corresponding framewise Betti information;
explain what repeated persistence reveals beyond a simpler dynamic baseline; and
state precisely why similar features in consecutive persistence diagrams have not thereby acquired a tracked identity.

